import numpy as np
import random

class Agent:
    def __init__(self, learning_rate=0.1, discount_factor=0.9, epsilon_start=1.0, epsilon_end=0.01, epsilon_decay=0.995, seed=None):
        self.lr = learning_rate
        self.gamma = discount_factor
        self.epsilon_start = epsilon_start
        self.epsilon_end = epsilon_end
        self.epsilon_decay = epsilon_decay
        self.q_table = {}

        if seed is not None:
            random.seed(seed)
            np.random.seed(seed)

        self.epsilon = epsilon_start

    def reset(self):
        """Resets the internal state of the agent if needed. For Q-learning, this usually means keeping the table but potentially resetting epsilon or internal counters."""
        # In standard Q-learning for TTT, we often keep the q_table across episodes.
        # However, sometimes 'reset' implies restarting an episode without clearing learned values.
        pass

    def get_q_values(self, state_hash):
        """Retrieves Q-values for a specific state."""
        if state_hash not in self.q_table:
            return [0.0] * 9
        return self.q_table[state_hash][:].copy()

    def choose_action(self, state_hash, legal_moves, epsilon):
        """Chooses an action based on epsilon-greedy policy."""
        if np.random.rand() < epsilon:
            # Exploration: pick a random legal move
            return np.random.choice(legal_moves)
        else:
            # Exploitation: pick the best legal move
            q_vals = self.get_q_values(state_hash)
            max_q = max(q_vals[i] for i in legal_moves)
            best_actions = [i for i in legal_moves if abs(q_vals[i] - max_q) < 1e-9]
            return np.random.choice(best_actions)

    def update(self, state_hash, action, reward, next_state_hash, done):
        """Updates the Q-value for the given state-action pair."""
        if state_hash not in self.q_table:
            self.q_table[state_hash] = np.zeros(9)

        current_q = self.q_table[state_hash][action]

        if done:
            target = reward
        else:
            next_q_vals = self.get_q_values(next_state_hash)
            max_next_q = max(next_q_vals) if any(v > -np.inf for v in next_q_vals) else 0.0
            target = reward + self.gamma * max_next_q

        new_q = current_q + self.lr * (target - current_q)
        self.q_table[state_hash][action] = new_q

        self.decay_epsilon()

    def decay_epsilon(self):
        """Decreases epsilon by the decay factor, but not below epsilon_end."""
        self.epsilon *= self.epsilon_decay
        if self.epsilon < self.epsilon_end:
            self.epsilon = self.epsilon_end

